export interface ImagePlaceholderOptions {
  HTMLAttributes: Record<string, unknown>;
  allowedMimeTypes?: Record<string, string[]>;
  maxFiles?: number;
  maxSize?: number;
  onDrop?: (files: File[], editor: Editor) => void;
  onDropRejected?: (files: File[], editor: Editor) => void;
  onEmbed?: (url: string, editor: Editor) => void;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    imagePlaceholder: {
      insertImagePlaceholder: () => ReturnType;
    };
  }
}

export const ImagePlaceholder = Node.create<ImagePlaceholderOptions>({
  addCommands() {
    return {
      insertImagePlaceholder:
        () =>
        ({ chain, state }: CommandProps) => {
          const { from } = state.selection;
          const node = this.type.create();
          return chain()
            .insertContentAt(from, node.toJSON())
            .setTextSelection(from + node.nodeSize)
            .run();
        },
    };
  },
  addNodeView() {
    return ReactNodeViewRenderer(ImagePlaceholderNode);
  },
  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },
  atom: true,
  group: "block",
  name: "imagePlaceholder",
  parseHTML() {
    return [{ tag: `div[data-type="${this.name}"]` }];
  },
  renderHTML({ HTMLAttributes }) {
    return [
      "div",
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        "data-type": this.name,
      }),
    ];
  },
});

"use client";

import type { NodeViewProps } from "@tiptap/react";
import { NodeViewWrapper } from "@tiptap/react";
import { ImageIcon, Link, Upload } from "lucide-react";
import type { DragEvent, FormEvent } from "react";
import { useCallback, useId, useState } from "react";

import { isValidUrl } from "../core/commands";
import { useToolbar } from "../core/context";
import { Button } from "../ui/button";
import { Input } from "../ui/input";
import { Popover } from "../ui/popover";
import { PopoverContent } from "../ui/popover-content";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../ui/tabs";
import { cn } from "../ui/utils";

const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
  e.preventDefault();
  e.stopPropagation();
};

export const ImagePlaceholderNode = ({
  editor,
  extension,
  getPos,
  node,
  selected,
}: NodeViewProps) => {
  const { labels } = useToolbar();
  const fileInputId = useId();
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");
  const [urlError, setUrlError] = useState(false);
  const [isDragActive, setIsDragActive] = useState(false);
  const [isDragReject, setIsDragReject] = useState(false);

  const replaceWithImage = useCallback(
    (src: string) => {
      const pos = getPos();
      if (typeof pos !== "number") {
        return;
      }
      editor
        .chain()
        .focus()
        .insertContentAt(
          { from: pos, to: pos + node.nodeSize },
          { attrs: { src, width: "60%" }, type: "image" }
        )
        .run();
    },
    [editor, getPos, node.nodeSize]
  );

  const handleAcceptedFiles = (files: File[]) => {
    for (const file of files) {
      const reader = new FileReader();
      reader.addEventListener("load", () =>
        replaceWithImage(reader.result as string)
      );
      reader.readAsDataURL(file);
    }
    extension.options.onDrop?.(files, editor);
  };

  const handleDragEnter = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragActive(true);
  };

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragActive(false);
    setIsDragReject(false);
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragActive(false);
    setIsDragReject(false);

    const { files } = e.dataTransfer;
    const accepted: File[] = [];
    const rejected: File[] = [];

    for (const file of files) {
      const mimeTypes = extension.options.allowedMimeTypes as
        | Record<string, string[]>
        | undefined;
      const tooLarge =
        (extension.options.maxSize as number | undefined) &&
        file.size > (extension.options.maxSize as number);

      if (
        mimeTypes &&
        !Object.keys(mimeTypes).some((type) => file.type.match(type))
      ) {
        rejected.push(file);
      } else if (tooLarge) {
        rejected.push(file);
      } else {
        accepted.push(file);
      }
    }

    if (rejected.length > 0) {
      setIsDragReject(true);
      extension.options.onDropRejected?.(rejected, editor);
    }

    if (accepted.length > 0) {
      handleAcceptedFiles(accepted);
    }
  };

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    handleAcceptedFiles([...(e.target.files || [])]);
  };

  const handleInsertEmbed = (e: FormEvent) => {
    e.preventDefault();
    if (!isValidUrl(url)) {
      setUrlError(true);
      return;
    }
    replaceWithImage(url);
    extension.options.onEmbed?.(url, editor);
  };

  const mimeTypeList = Object.keys(
    (extension.options.allowedMimeTypes as
      | Record<string, string[]>
      | undefined) ?? {
      "image/*": ["image/*"],
    }
  ).join(",");

  const triggerClass = cn(
    "ext-image-placeholder-trigger flex w-full cursor-pointer items-center gap-3 rounded-md border-none bg-accent p-3 text-left text-[0.875rem] text-accent-foreground [transition:background-color_150ms_ease-out,color_150ms_ease-out,box-shadow_150ms_ease-out] hover:bg-secondary hover:text-secondary-foreground focus-visible:shadow-[0_0_0_2px_var(--ring)] focus-visible:outline-none [&>svg]:size-6 [&>svg]:shrink-0",
    selected &&
      "ext-image-placeholder-trigger--selected shadow-[0_0_0_2px_var(--ring)] outline-none"
  );

  const uploadZoneClass = cn(
    "ext-image-upload-zone my-2 rounded-md border border-dashed border-border text-[0.875rem] [transition:border-color_150ms_ease-out,background-color_150ms_ease-out] hover:bg-secondary",
    isDragActive &&
      "ext-image-upload-zone--dragging border-primary bg-secondary",
    isDragReject &&
      "ext-image-upload-zone--reject border-destructive bg-destructive/10"
  );

  return (
    <NodeViewWrapper className="ext-image-placeholder w-full">
      <Popover
        open={open}
        onOpenChange={setOpen}
        trigger={
          <button
            aria-label={labels.imagePlaceholder}
            className={triggerClass}
            type="button"
          >
            <ImageIcon />
            {labels.imagePlaceholder}
          </button>
        }
      >
        <PopoverContent className="ext-image-placeholder-popover w-md max-w-[min(calc(100vw-2rem),28rem)] p-3">
          <Tabs defaultValue="upload">
            <TabsList>
              <TabsTrigger value="upload">
                <Upload />
                Upload
              </TabsTrigger>
              <TabsTrigger value="url">
                <Link />
                Embed link
              </TabsTrigger>
            </TabsList>
            <TabsContent value="upload">
              <div
                onDragEnter={handleDragEnter}
                onDragLeave={handleDragLeave}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                className={uploadZoneClass}
              >
                <input
                  type="file"
                  accept={mimeTypeList}
                  multiple={
                    (extension.options.maxFiles as number | undefined) !== 1
                  }
                  onChange={handleFileInputChange}
                  className="ext-sr-only sr-only"
                  id={fileInputId}
                />
                <label
                  htmlFor={fileInputId}
                  className="ext-image-upload-label flex h-28 w-full cursor-pointer flex-col items-center justify-center text-center select-none [&>svg]:mx-auto [&>svg]:mb-2 [&>svg]:size-6 [&>svg]:shrink-0"
                >
                  <Upload />
                  Drag & drop or click to upload
                </label>
              </div>
            </TabsContent>
            <TabsContent value="url">
              <form
                onSubmit={handleInsertEmbed}
                className="ext-image-embed grid gap-2"
              >
                <Input
                  value={url}
                  onChange={(e) => {
                    setUrl(e.target.value);
                    if (urlError) {
                      setUrlError(false);
                    }
                  }}
                  placeholder="Paste the image link..."
                />
                {urlError ? (
                  <p className="ext-image-error m-0 text-[0.75rem] text-destructive">
                    Please enter a valid URL
                  </p>
                ) : null}
                <Button
                  type="submit"
                  className="ext-image-embed-submit w-full border-transparent bg-primary text-primary-foreground hover:bg-[color-mix(in_srgb,var(--primary)_85%,black)] hover:text-primary-foreground"
                >
                  Embed Image
                </Button>
                <p className="ext-image-hint m-0 text-center text-[0.75rem] text-muted-foreground">
                  Works with any image from the web
                </p>
              </form>
            </TabsContent>
          </Tabs>
        </PopoverContent>
      </Popover>
    </NodeViewWrapper>
  );
};

"use client";

import { Image as TiptapImage } from "@tiptap/extension-image";
import {
  NodeViewContent,
  NodeViewWrapper,
  ReactNodeViewRenderer,
} from "@tiptap/react";
import type { NodeViewProps } from "@tiptap/react";
import {
  AlignCenter,
  AlignLeft,
  AlignRight,
  Copy,
  Maximize2,
  MoreHorizontal,
  Trash2,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";

import { Button } from "../ui/button";
import { DropdownMenuContent } from "../ui/dropdown-content";
import { DropdownMenuItem } from "../ui/dropdown-item";
import { DropdownMenu } from "../ui/dropdown-menu";
import { DropdownMenuSeparator } from "../ui/dropdown-separator";
import { Separator } from "../ui/separator";

const RESIZE_CLASS =
  "ext-image-resize absolute inset-y-0 z-20 flex w-4 cursor-col-resize touch-none items-center";

const RESIZE_BAR_CLASS =
  "ext-image-resize-bar h-16 w-1 rounded-full bg-foreground/30 opacity-0 [transition:opacity_150ms_ease-out] group-hover/image:opacity-100 group-[.ext-image-view--resizing]/image:opacity-100";

const ResizableImageNode = ({
  node,
  editor,
  selected,
  deleteNode,
  updateAttributes,
  getPos,
}: NodeViewProps) => {
  const imageRef = useRef<HTMLImageElement | null>(null);
  const nodeRef = useRef<HTMLDivElement | null>(null);
  const [resizing, setResizing] = useState(false);
  const [resizingPosition, setResizingPosition] = useState<"left" | "right">(
    "left"
  );
  const [resizeInitialWidth, setResizeInitialWidth] = useState(0);
  const [resizeInitialMouseX, setResizeInitialMouseX] = useState(0);
  const [openedMore, setOpenedMore] = useState(false);
  const [actionBarRect, setActionBarRect] = useState<{
    top: number;
    right: number;
  } | null>(null);

  useEffect(() => {
    if (!selected || resizing) {
      return;
    }
    let frame = 0;
    const loop = () => {
      const el = nodeRef.current;
      if (el) {
        const rect = el.getBoundingClientRect();
        setActionBarRect({ right: rect.right, top: rect.bottom + 12 });
      }
      frame = requestAnimationFrame(loop);
    };
    frame = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frame);
  }, [selected, resizing]);

  const resize = (event: MouseEvent) => {
    if (!resizing) {
      return;
    }
    let dx = event.clientX - resizeInitialMouseX;
    if (resizingPosition === "left") {
      dx = resizeInitialMouseX - event.clientX;
    }
    const newWidth = Math.max(resizeInitialWidth + dx, 150);
    const parentWidth = nodeRef.current?.parentElement?.offsetWidth || 0;
    if (newWidth < parentWidth) {
      updateAttributes({ width: newWidth });
    }
  };

  const endResize = () => {
    setResizing(false);
    setResizeInitialMouseX(0);
    setResizeInitialWidth(0);
  };

  const handleMouseDown =
    (position: "left" | "right") =>
    (event: React.MouseEvent<HTMLDivElement>) => {
      event.preventDefault();
      setResizing(true);
      setResizingPosition(position);
      setResizeInitialMouseX(event.clientX);
      if (imageRef.current) {
        setResizeInitialWidth(imageRef.current.offsetWidth);
      }
    };

  const handleTouchStart =
    (position: "left" | "right") => (event: React.TouchEvent) => {
      event.preventDefault();
      const touch = event.touches.item(0);
      if (!touch) {
        return;
      }
      setResizing(true);
      setResizingPosition(position);
      setResizeInitialMouseX(touch.clientX);
      if (imageRef.current) {
        setResizeInitialWidth(imageRef.current.offsetWidth);
      }
    };

  const handleTouchMove = (event: TouchEvent) => {
    if (!resizing) {
      return;
    }
    const touch = event.touches.item(0);
    if (!touch) {
      return;
    }
    let dx = touch.clientX - resizeInitialMouseX;
    if (resizingPosition === "left") {
      dx = resizeInitialMouseX - touch.clientX;
    }
    const newWidth = Math.max(resizeInitialWidth + dx, 150);
    const parentWidth = nodeRef.current?.parentElement?.offsetWidth || 0;
    if (newWidth < parentWidth) {
      updateAttributes({ width: newWidth });
    }
  };

  const handleTouchEnd = () => {
    setResizing(false);
    setResizeInitialMouseX(0);
    setResizeInitialWidth(0);
  };

  useEffect(() => {
    window.addEventListener("mousemove", resize);
    window.addEventListener("mouseup", endResize);
    window.addEventListener("touchmove", handleTouchMove);
    window.addEventListener("touchend", handleTouchEnd);
    window.addEventListener("touchcancel", handleTouchEnd);
    return () => {
      window.removeEventListener("mousemove", resize);
      window.removeEventListener("mouseup", endResize);
      window.removeEventListener("touchmove", handleTouchMove);
      window.removeEventListener("touchend", handleTouchEnd);
      window.removeEventListener("touchcancel", handleTouchEnd);
    };
  }, [
    resizing,
    resizeInitialMouseX,
    resizeInitialWidth,
    resize,
    handleTouchMove,
  ]);

  const duplicate = () => {
    const pos = getPos();
    if (typeof pos !== "number" || !editor || editor.isDestroyed) {
      return;
    }
    editor
      .chain()
      .focus()
      .insertContentAt(pos + node.nodeSize, node.toJSON())
      .run();
  };

  const viewClass = [
    "ext-image-view group/image",
    node.attrs.align === "left" ? "ext-image-view--left" : "",
    node.attrs.align === "center" ? "ext-image-view--center" : "",
    node.attrs.align === "right" ? "ext-image-view--right" : "",
    selected ? "ext-image-view--selected" : "",
    resizing ? "ext-image-view--resizing" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <>
      <NodeViewWrapper
        ref={nodeRef}
        className={viewClass}
        style={{ width: node.attrs.width }}
      >
        <img
          ref={imageRef}
          className="ext-image-view-img"
          src={node.attrs.src}
          alt={node.attrs.alt}
          title={node.attrs.title}
        />
        {node.attrs.title ? (
          <NodeViewContent className="ext-image-view-caption">
            {node.attrs.title}
          </NodeViewContent>
        ) : null}

        {editor?.isEditable && (
          <>
            <div
              className={`${RESIZE_CLASS} ext-image-resize--left left-0 justify-start`}
              onMouseDown={handleMouseDown("left")}
              onTouchStart={handleTouchStart("left")}
            >
              <div className={RESIZE_BAR_CLASS} />
            </div>
            <div
              className={`${RESIZE_CLASS} ext-image-resize--right right-0 justify-end`}
              onMouseDown={handleMouseDown("right")}
              onTouchStart={handleTouchStart("right")}
            >
              <div className={RESIZE_BAR_CLASS} />
            </div>
          </>
        )}
      </NodeViewWrapper>

      {editor?.isEditable &&
        selected &&
        actionBarRect &&
        !resizing &&
        createPortal(
          <div
            className="ext-image-actions ext-image-actions--floating fixed z-60 mt-0 flex items-center gap-1 rounded-lg border border-border bg-popover p-1 text-popover-foreground opacity-100 shadow-[0_4px_16px_rgba(0,0,0,0.08)]"
            style={{
              right: window.innerWidth - actionBarRect.right,
